	devices := NewDGX1VoltaNode().Devices()
	policy := NewStaticDGX1Policy(GPUTypeVolta)

	tests := []PolicyAllocTest{
		{
			"Must include with allocation size 1",
			devices,
			[]int{0, 1, 2, 3, 4, 5, 6, 7},
			[]int{4},
