			devices,
			[]int{0, 1, 2, 3, 4, 5, 6, 7},
			[]int{4},
			2,
			[]int{4, 7},
		},
		{
			"Must include with allocation size 4",
			devices,
			[]int{0, 1, 2, 3, 4, 5, 6, 7},
			[]int{4},
			4,
			[]int{4, 5, 6, 7},
		},
		{
			"Must include with unavailable device",
			devices,
			[]int{1, 2, 3, 4, 5, 6, 7},
			[]int{0, 1, 2, 3},
			4,
			[]int{},
		},
		{
			"Must include with devices not in valid set",
			devices,
			[]int{0, 1, 2, 3, 4, 5, 6, 7},
			[]int{0, 2, 4, 6},
			4,
			[]int{},
